o.status <> 'CANCELLED'
AND o.order_time >= #{begin}
AND o.order_time < #{end}
AND o.store_id = #{storeId}

mapper.select:
SELECT s.id AS store_id, s.name AS store_name, s.platform, s.marketplace, COUNT(o.id) AS orders, COALESCE((SELECT SUM(oi.qty) FROM ecom_order_item oi JOIN ecom_order o2 ON o2.id = oi.order_id WHERE o2.store_id = s.id AND o2.status <> 'CANCELLED' AND o2.order_time >= #{begin} AND o2.order_time < #{end}), 0) AS qty, COALESCE(SUM(o.total_base), 0) AS sales, COALESCE(SUM(), 0) AS fees, COALESCE(SUM(), 0) AS refund, COALESCE(SUM(o.cost_amount), 0) AS cost, COALESCE(SUM(o.shipping_cost), 0) AS shipping, COALESCE(SUM(o.profit), 0) AS profit FROM ecom_store s LEFT JOIN ecom_order o ON o.store_id = s.id AND
s.id = #{storeId}
GROUP BY s.id, s.name, s.platform, s.marketplace ORDER BY sales DESC, s.id

SELECT si.item_type, COALESCE(SUM(si.amount * st.exchange_rate), 0) AS amount
FROM ecom_settlement_item si
JOIN ecom_settlement st ON st.id = si.settlement_id

    st.period_end >= #{begin}
    AND st.period_start <= #{end}
    AND st.store_id = #{storeId}

GROUP BY si.item_type
ORDER BY si.item_type

SELECT a.store_id AS "storeId", s.currency, a.seller_sku AS "sellerSku", SUM(a.spend) AS spend
FROM ecom_ad_daily a
JOIN ecom_store s ON s.id = a.store_id

    a.ad_date >= #{begin}
    AND a.ad_date <= #{end}
    AND a.store_id = #{storeId}

GROUP BY a.store_id, s.currency, a.seller_sku

SELECT a.store_id AS "storeId", s.currency, SUM(a.spend) AS spend
FROM ecom_ad_daily a
JOIN ecom_store s ON s.id = a.store_id

    a.ad_date >= #{begin}
    AND a.ad_date <= #{end}
    AND a.store_id = #{storeId}

GROUP BY a.store_id, s.currency
